export const part = 3;
export const html = "<p class=\"lead\">پرسش‌های مصاحبه با جواب کوتاه، جدول واژهٔ فارسی/انگلیسی، و مسیر بعد از کتاب. اگر بتوانی سه درخت و DAG را روی کاغذ بکشی، بیشتر سؤال‌ها همان مدل‌اند.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>به پرسش‌های سطح‌بندی‌شده با مدل سه‌درخت جواب بدهی</li>\n<li>اصطلاح انگلیسی را با معادل دقیق فارسی بگویی</li>\n<li>مسیر یادگیری بعد از این مرجع را بدانی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🎤 پرسش‌های مصاحبه (با پاسخ کوتاه)</span></span></h2>\n<p><strong>Junior</strong></p>\n<ul>\n<li>Git چیست؟ سیستم نسخه‌بندی توزیع‌شده مبتنی بر snapshot و محتوا-آدرس.</li>\n<li>staging یعنی چه؟ پیش‌نویس کامیت؛ Index.</li>\n<li>تفاوت clone و fork؟ clone محلی است؛ fork کپی حساب‌محور روی GitHub.</li>\n<li><code>pull</code> در برابر <code>fetch</code>؟ pull = fetch + ادغام/rebase.</li>\n</ul>\n<p><strong>Mid</strong></p>\n<ul>\n<li>merge در برابر rebase؟ حفظ گره در برابر بازنویسی خطی؛ rebase فقط روی شاخهٔ شخصی.</li>\n<li><code>reset --soft/--mixed/--hard</code>؟ کدام درخت‌ها حرکت می‌کنند (فصل ۸).</li>\n<li><code>A...B</code> در diff؟ از جد مشترک؛ همان نمای PR.</li>\n<li>چرا commit amend هش را عوض می‌کند؟ هویت شیء از محتواست.</li>\n<li>force-with-lease چیست؟ force مشروط به نخوردن کار دیگران.</li>\n</ul>\n<p><strong>Senior / Staff</strong></p>\n<ul>\n<li>DAG و چرا مهم است؟ توپولوژی تاریخچه؛ merge دو والد، rebase گره جدید.</li>\n<li>revert یک merge؟ <code>-m 1</code> و پیامد merge دوباره.</li>\n<li>Ruleset در برابر branch protection؟ لایه‌بندی، الگو، bypass، ارث سازمانی.</li>\n<li>OIDC در Actions؟ هویت کوتاه‌عمر به ابر بدون کلید ماندگار.</li>\n<li>چگونه باگ را در ۱۰ هزار کامیت پیدا می‌کنی؟ <code>bisect run</code> + تست قطعی.</li>\n<li>monorepo در Git چگونه زنده می‌ماند؟ partial clone، sparse cone، path-filter CI، گاهی Scalar.</li>\n<li>PR عامل AI را چطور کنترل می‌کنی؟ draft، required review غیرنویسنده، دستورالعمل، CI بعد از Approve.</li>\n</ul>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">تمرین مصاحبه</div>\n<p>جواب را ۲ دقیقه روی کاغذ بکش نه حفظ کن. اگر سه‌درخت و DAG را کشیدی، ۸۰٪ پرسش‌ها حل است.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">📚 واژه‌نامه فارسی — انگلیسی</span></span></h2>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>فارسی</th>\n<th>English</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>مخزن</td>\n<td>Repository</td>\n</tr>\n<tr>\n<td>درخت کاری</td>\n<td>Working Tree</td>\n</tr>\n<tr>\n<td>نمایه / استیج</td>\n<td>Index / Staging Area</td>\n</tr>\n<tr>\n<td>کامیت / ثبت</td>\n<td>Commit</td>\n</tr>\n<tr>\n<td>شاخه</td>\n<td>Branch</td>\n</tr>\n<tr>\n<td>تگ</td>\n<td>Tag</td>\n</tr>\n<tr>\n<td>اشارهٔ HEAD</td>\n<td>HEAD</td>\n</tr>\n<tr>\n<td>جداشده</td>\n<td>Detached HEAD</td>\n</tr>\n<tr>\n<td>واکشی</td>\n<td>Fetch</td>\n</tr>\n<tr>\n<td>ادغام</td>\n<td>Merge</td>\n</tr>\n<tr>\n<td>بازچینش</td>\n<td>Rebase</td>\n</tr>\n<tr>\n<td>گزینش گیلاس</td>\n<td>Cherry-pick</td>\n</tr>\n<tr>\n<td>خنثی‌سازی</td>\n<td>Revert</td>\n</tr>\n<tr>\n<td>بازیابی فایل</td>\n<td>Restore</td>\n</tr>\n<tr>\n<td>بازنشانی اشاره‌گر</td>\n<td>Reset</td>\n</tr>\n<tr>\n<td>قفسهٔ موقت</td>\n<td>Stash</td>\n</tr>\n<tr>\n<td>درخت کار دوم</td>\n<td>Worktree</td>\n</tr>\n<tr>\n<td>تعارض</td>\n<td>Conflict</td>\n</tr>\n<tr>\n<td>درخواست ادغام</td>\n<td>Pull Request</td>\n</tr>\n<tr>\n<td>انشعاب حساب</td>\n<td>Fork</td>\n</tr>\n<tr>\n<td>بالادست</td>\n<td>Upstream</td>\n</tr>\n<tr>\n<td>ردیابی</td>\n<td>Tracking Branch</td>\n</tr>\n<tr>\n<td>گراف جهت‌دار بدون دور</td>\n<td>DAG</td>\n</tr>\n<tr>\n<td>تودهٔ فشرده</td>\n<td>Packfile</td>\n</tr>\n<tr>\n<td>جمع‌آوری زباله</td>\n<td>Garbage Collection</td>\n</tr>\n<tr>\n<td>قلاب</td>\n<td>Hook</td>\n</tr>\n<tr>\n<td>مجموعه قواعد</td>\n<td>Ruleset</td>\n</tr>\n<tr>\n<td>صاحبان کد</td>\n<td>CODEOWNERS</td>\n</tr>\n<tr>\n<td>گواهی ساخت</td>\n<td>Attestation</td>\n</tr>\n<tr>\n<td>کلون ناقص</td>\n<td>Partial Clone</td>\n</tr>\n<tr>\n<td>نادیده‌گیری تنک</td>\n<td>Sparse Checkout</td>\n</tr>\n<tr>\n<td>امضای تأییدشده</td>\n<td>Verified Signature</td>\n</tr>\n<tr>\n<td>عامل کدنویس</td>\n<td>Coding Agent</td>\n</tr>\n</tbody>\n</table></div><p>جدول را از راست به چپ بخوان؛ ستون انگلیسی برای جست‌وجوی مستندات رسمی است.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🗺️ نقشه راه بعد از کتاب</span></span></h2>\n<ol>\n<li><strong>یک ماه:</strong> همهٔ کار روزانه فقط با VS Code + <code>gh</code>؛ ترمینال برای rebase -i.</li>\n<li><strong>سه ماه:</strong> Maintain یک ریپوی عمومی؛ ریویو PR دیگران؛ Actions با OIDC روی یک ابر.</li>\n<li><strong>شش ماه:</strong> حادثهٔ ساختگی: secret leak + بازیابی با filter-repo روی مخزن آزمایشی.</li>\n<li><strong>یک سال:</strong> طراحی Ruleset سازمان، CODEOWNERS، Environments، Immutable Release.</li>\n<li><strong>مطالعهٔ بعدی:</strong> Pro Git (رسمی)، مستندات GitHub Actions، SLSA، داخلی reftable، مدل مجوز GitHub Apps.</li>\n</ol>\n<p class=\"keep-next\">مجموعهٔ فارسی همراه:</p>\n<ul>\n<li>مرجع JavaScript ES2025 — <a href=\"https://github.com/rezaian-dev/javascript-persian-guide\">javascript-persian-guide</a></li>\n<li>همین کتاب را هر فصل که Git عوض شد (۳.۰) با PR به‌روز کن</li>\n</ul>\n<div class=\"callout callout-summary\"><div class=\"callout-title\">جمع‌بندی فصل</div>\n<p>اگر بتوانی روی کاغذ سه درخت، DAG، Undo عمومی/خصوصی و مسیر PR را بکشی، سطح عالی را لمس کرده‌ای. بقیه تجربه است.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ پایان مسیر کتاب</span></span></h2>\n<ul>\n<li>مدل ذهنی را به تیم‌ات آموزش بده — بهترین تثبیت</li>\n<li>یک PR آموزشی روی ریپوی خودت باز کن و ریویو بخواه</li>\n<li>ستاره و Issue روی راهنماهای فارسی یعنی این مسیر زنده می‌ماند</li>\n</ul>\n<p><strong>حالا برو تاریخچه را درست بنویس.</strong></p>";
export default { n, num, title, label, part, html };
